Outcome<MilitaryOrders> make_military_ai(const MilitaryBattleRecord& b,const MilitaryBattleCatalog& c,const MilitaryDamageSources& sources){auto r=sources_valid(b,sources);if(!r.ok)return {false,{},r.error};r=validate_military_battle(b,c);if(!r.ok)return {false,{},r.error};if(b.phase!="planning")return error<MilitaryOrders>("MilitaryBattleNotPlanning");MilitaryOrders plans;for(auto& id:ids(b)){if(military_unit_routing(*unit(b,id))){auto routed=make_military_rout_order(b,c,id);if(!routed.ok)return {false,{},routed.error};plans.emplace_back(id,std::move(routed.value));continue;}if(has(b.command_unit_ids,id)||!operational(*unit(b,id)))continue;auto p=ai_order(b,c,id,sources);auto q=order(b,c,id,p,sources);if(!q.ok)return error<MilitaryOrders>("MilitaryAICannotPlan",id+"/"+q.error.original.code);plans.emplace_back(id,p);}return {true,std::move(plans),{}};}
